PREFIX in: <http://data.world/schema/insurance/>

SELECT ?policyNumber ?agentId
       (SUM(COALESCE(?lossPaymentVal, 0) + COALESCE(?lossReserveVal, 0)) AS ?totalLoss)
       (SUM(COALESCE(?premiumVal, 0)) AS ?totalPremium)
       ((SUM(COALESCE(?lossPaymentVal, 0) + COALESCE(?lossReserveVal, 0))) / SUM(COALESCE(?premiumVal, 0)) AS ?lossRatio)
WHERE {
  SERVICE <mapped> {
    ?policy a in:Policy ;
            in:policyNumber ?policyNumber ;
            in:soldByAgent ?agent .

    ?agent in:agentId ?agentId .

    ?coverage a in:PolicyCoverageDetail ;
              in:hasPolicy ?policy ;
              in:hasPremiumAmount ?premiumNode .

    ?premiumNode in:premiumAmount ?premiumVal .

    OPTIONAL {
      ?claim a in:Claim ;
             in:against ?coverage .
      OPTIONAL {
        ?claim in:hasLossPayment ?lossPaymentNode .
        ?lossPaymentNode in:lossPaymentAmount ?lossPaymentVal .
      }
      OPTIONAL {
        ?claim in:hasLossReserve ?lossReserveNode .
        ?lossReserveNode in:lossReserveAmount ?lossReserveVal .
      }
    }
  }
}
GROUP BY ?policyNumber ?agentId
HAVING (SUM(COALESCE(?premiumVal, 0)) > 0)

PREFIX in: <http://data.world/schema/insurance/>

SELECT ?policyNumber ?effectiveDate ?expirationDate
WHERE {
  SERVICE <mapped> {
    ?policy a in:Policy ;
            in:policyNumber ?policyNumber ;
            in:policyEffectiveDate ?effectiveDate ;
            in:policyExpirationDate ?expirationDate .
  }
}
ORDER BY ?policyNumber

PREFIX in: <http://data.world/schema/insurance/>

SELECT ?claimNumber ?policyNumber ?policyHolderId ?premiumAmountPaid ?agentId
       ?lossPaymentAmount ?lossReserveAmount ?expensePaymentAmount ?expenseReserveAmount
WHERE {
  SERVICE <mapped> {
    ?claim a in:Claim ;
           in:claimNumber ?claimNumber ;
           in:against ?coverage .

    ?coverage a in:PolicyCoverageDetail ;
              in:hasPolicy ?policy ;
              in:hasPremiumAmount ?premium .

    ?policy a in:Policy ;
            in:policyNumber ?policyNumber ;
            in:hasPolicyHolder ?policyHolder ;
            in:soldByAgent ?agent .

    ?policyHolder in:policyHolderId ?policyHolderId .
    ?premium in:premiumAmount ?premiumAmountPaid .
    ?agent in:agentId ?agentId .

    OPTIONAL {
      ?claim in:hasLossPayment ?lossPayment .
      ?lossPayment in:lossPaymentAmount ?lossPaymentAmount .
    }

    OPTIONAL {
      ?claim in:hasLossReserve ?lossReserve .
      ?lossReserve in:lossReserveAmount ?lossReserveAmount .
    }

    OPTIONAL {
      ?claim in:hasExpensePayment ?expensePayment .
      ?expensePayment in:expensePaymentAmount ?expensePaymentAmount .
    }

    OPTIONAL {
      ?claim in:hasExpenseReserve ?expenseReserve .
      ?expenseReserve in:expenseReserveAmount ?expenseReserveAmount .
    }
  }
}

PREFIX in: <http://data.world/schema/insurance/>

SELECT ?catastropheName ?policyNumber
       (SUM(?lossPaymentVal) AS ?totalLossPayment)
       (SUM(?lossReserveVal) AS ?totalLossReserve)
       (SUM(?expensePaymentVal) AS ?totalExpensePayment)
       (SUM(?expenseReserveVal) AS ?totalExpenseReserve)
       (SUM(?lossPaymentVal + ?lossReserveVal + ?expensePaymentVal + ?expenseReserveVal) AS ?totalLoss)
WHERE {
  SERVICE <mapped> {
    ?claim a in:Claim ;
           in:hasCatastrophe ?catastrophe ;
           in:against ?coverage .

    ?catastrophe in:catastropheName ?catastropheName .
    ?coverage in:hasPolicy ?policy .
    ?policy in:policyNumber ?policyNumber .

    OPTIONAL {
      ?claim in:hasLossPayment ?lp .
      ?lp in:lossPaymentAmount ?lpAmt .
    }

    OPTIONAL {
      ?claim in:hasLossReserve ?lr .
      ?lr in:lossReserveAmount ?lrAmt .
    }

    OPTIONAL {
      ?claim in:hasExpensePayment ?ep .
      ?ep in:expensePaymentAmount ?epAmt .
    }

    OPTIONAL {
      ?claim in:hasExpenseReserve ?er .
      ?er in:expenseReserveAmount ?erAmt .
    }

    BIND(COALESCE(xsd:decimal(?lpAmt), 0) AS ?lossPaymentVal)
    BIND(COALESCE(xsd:decimal(?lrAmt), 0) AS ?lossReserveVal)
    BIND(COALESCE(xsd:decimal(?epAmt), 0) AS ?expensePaymentVal)
    BIND(COALESCE(xsd:decimal(?erAmt), 0) AS ?expenseReserveVal)
  }
}
GROUP BY ?catastropheName ?policyNumber
ORDER BY ?catastropheName ?policyNumber

PREFIX in: <http://data.world/schema/insurance/>

SELECT ?agentId ?policyNumber ?claimNumber ?expensePaymentAmount
WHERE {
  SERVICE <mapped> {
    ?policy a in:Policy ;
            in:policyNumber ?policyNumber ;
            in:soldByAgent ?agent .

    ?agent a in:Agent ;
           in:agentId ?agentId .

    ?coverage a in:PolicyCoverageDetail ;
              in:hasPolicy ?policy .

    ?claim a in:Claim ;
           in:claimNumber ?claimNumber ;
           in:against ?coverage ;
           in:hasExpensePayment ?expensePayment .

    ?expensePayment a in:ExpensePayment ;
                    in:expensePaymentAmount ?expensePaymentAmount .
  }
}
ORDER BY ?agentId ?policyNumber ?claimNumber
